param([ValidateSet('build','safety','q1024','q8192')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-packed-probability-20260920-r1';$seed='D:\projects\AIMA-public-compact-suffix-query-20260919-r2';$sha='6f54c7bfed4e2ca9ce471ae99a8632487b57426f';$bundle='D:\projects\packed-probability-6f54c7b.bundle'
$m=[IO.File]::ReadAllText('D:\projects\packed-probability-native-source-r1.json')|ConvertFrom-Json
if($m.source_commit -ne $sha -or $m.repo.Replace('/','\') -ne $repo){throw 'Source manifest mismatch'}
$previous=[IO.File]::ReadAllText((Join-Path $m.previous_model_remote 'run-record.json'))|ConvertFrom-Json
if($previous.host -ne 'baiying' -or -not $previous.host_checks_pass -or $previous.after_processes -or
 @($previous.host_checks.PSObject.Properties|Where-Object {-not $_.Value}).Count){throw 'Previous model cleanup is incomplete'}
if($previous.spec.command_file_sha256 -ne $m.previous_model_command_sha256){throw 'Previous model command mismatch'}
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'f672511ad505940a2320fb373295587111e45858fcd6670f7ee29f00122cee1d'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){& git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'};& git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\packed-probability';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\packed_probability_selftest.cpp';$exe=Join-Path $build 'packed-probability.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceInputs=@()
foreach($property in $m.source_sha256.PSObject.Properties){
 $file=Join-Path $repo $property.Name
 if((Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $property.Value){throw ('Source hash mismatch: '+$property.Name)}
 $sourceInputs+=@{file=$file;sha256=$property.Value}
}
if($sourceInputs.Count -ne 57 -or $m.local_compilation_inputs -ne 56){throw 'Compilation inventory changed'}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='D:\models\Qwen3.6-35B-A3B; original GB10 16384-prefix plus1024 suffix layer3 Q/K/V';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;purpose='Compare separate BF16, tagged FP32 and packed BF16 probabilities inside consumed score rows using shared original long-attention arithmetic. Validate every probability, raw native and replayed surface, candidate, untouched score word, guard and owner stage. Original GB10 context is comparison-only; repeated capture rows are component coverage only. No model or memory/performance acceptance.'}
$spec.previous_model_run_record_sha256=(Get-FileHash (Join-Path $m.previous_model_remote 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant()
$safety='D:\projects\AIMA-public-native-exp2-delta-20260917\build\native-exp2-delta-test-r1\run-record.json';if((Get-FileHash $safety -Algorithm SHA256).Hash.ToLowerInvariant() -ne '46a1fbaca781b00f04c3d4e3041834e8ba438e563c4c6dc3fabafc1b22126bd2'){throw 'Full-domain prerequisite changed'}
$qkSafety='D:\projects\AIMA-public-microtile-exact-qk-20260917\build\microtile-exact-qk-test-r1\run-record.json';if((Get-FileHash $qkSafety -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'd7da7e549cdf861f246d78dbfbdcb87faf152fd1920f2d19a33b9e6f069db0c6'){throw 'QK safety prerequisite changed'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe';$spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','-DQRT_CK_SM121_INTERPOLATED_EXP2=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=[int]$m.native_timeouts_seconds.$Action
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 foreach($file in $meta.source_inputs){if((Get-FileHash $file.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Build source changed'}}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant();$table='D:\projects\sm121-exp2-interpolated-b5752a88.bin';if((Get-FileHash $table -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'b5752a88488d8e6382cc99a897ef822e97758e0a782930c174954a5299126eec'){throw 'Exp2 table changed'}
 $qroot='D:\projects\suffix-attention-replay-inputs-r1'
 $q=Join-Path $qroot 'query-bf16.bin'
 $k=Join-Path $qroot 'key-bf16.bin'
 $v=Join-Path $qroot 'value-bf16.bin'
 $reference=Join-Path $qroot 'expected-output-bf16.bin'
 $inputManifest=Join-Path $qroot 'manifest.json'
 if((Get-FileHash $inputManifest -Algorithm SHA256).Hash.ToLowerInvariant() -ne '819e15c5d36e6bf1deaf862839d83365b116e39a37526f90094e9f64bce652f1'){throw 'Original GB10 manifest changed'}
 $spec.reference_manifest_sha256='819e15c5d36e6bf1deaf862839d83365b116e39a37526f90094e9f64bce652f1';$spec.reference_manifest=[IO.File]::ReadAllText($inputManifest)|ConvertFrom-Json
 $rcp='D:\projects\sm121-attention-rcp-d2e55754.bin'
 $inputs=@(@{file=$q;sha256='d4445d9a03f92b1586eec9ccd12a794e742552613ed09a3b2ca28b0847ec1612'},
 @{file=$k;sha256='dbfa44ac0e63e961397cba100589a373fda702c18121dd0ea42fbbef442310bd'},
 @{file=$v;sha256='79eed4f839c165b451e4f33a54eafd2031c2876cfd19120cce9a18e36fc464a4'},
 @{file=$reference;sha256='8e49075c5d36e29c17498f70e5bfac083f66b88d041878797c4a5f44bf8b7517'},
 @{file=$table;sha256='b5752a88488d8e6382cc99a897ef822e97758e0a782930c174954a5299126eec'},
 @{file=$rcp;sha256='d2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39'})
 foreach($input in $inputs){if((Get-FileHash $input.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $input.sha256){throw 'Capture or table fingerprint changed'}}
 $tokens=if($Action -eq 'q1024'){1024}else{8192}
 $spec.input_files=$inputs;$spec.reference_is_compute_input=$false;$spec.reference_host='gb10-4t';$spec.reference_context_tokens=1024;$spec.original_gb10_context_cells=4194304;$spec.query_origin=16384
 $spec.tokens=$tokens;$spec.repeated_rows=$tokens-1024;$spec.query_batch=128;$spec.same_executable_comparison=$true
 $spec.executable=$exe;$spec.arguments=@([string]$tokens,$q,$k,$v,$reference,$table,$rcp);$timeout=[int]$m.native_timeouts_seconds.$Action
 if($Action -eq 'safety'){
  $tokens=0;$spec.tokens=0;$spec.repeated_rows=0;$spec.model='none; generated attention operands';$spec.input_files=@($inputs[4],$inputs[5])
  $spec.arguments=@('safety',$table,$rcp)
  $spec.reference_context_tokens=0;$spec.original_gb10_context_cells=0;$spec.reference_host='none; generated operands'
  $spec.generated_cases=60;$spec.independent_cpu_dots_per_case_per_candidate=128;$spec.candidate_dot_checks_per_case=256;$spec.storage_formats=3
  $spec.Remove('reference_manifest');$spec.Remove('reference_manifest_sha256')
 }else{
  $prior=[IO.File]::ReadAllText((Join-Path $repo 'build\packed-probability-safety-r1\run-record.json'))|ConvertFrom-Json
  if($prior.reason -ne 'completed' -or $prior.exit_code -ne 0 -or -not $prior.host_checks_pass){throw 'Safety prerequisite failed'}
  $spec.safety_run_sha256=(Get-FileHash (Join-Path $repo 'build\packed-probability-safety-r1\run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant()
 }

}
$specPath=Join-Path $build ($Action+'-spec-r1.json');$out=Join-Path $repo ('build\packed-probability-'+$Action+'-r1')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native subgroup diagnostic failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($Action -eq 'safety'){
  if($reports.Count -ne 1 -or $reports[0].kind -ne 'packed_probability_safety' -or $reports[0].cases -ne 60 -or
   $reports[0].original_cpu_dot_checks -ne 15360 -or $reports[0].storage_formats -ne 3 -or $reports[0].maximum_keys -ne 264736 -or $reports[0].stages -ne 5 -or
   -not $reports[0].candidate_identity -or -not $reports[0].both_bound_policies -or -not $reports[0].score_stage_before_overwrite -or
   $reports[0].model_acceptance){throw 'Generated in-place probability boundary failed'}
 }else{
  if($reports.Count -ne 3 -or $reports[0].mode -ne 0 -or $reports[1].mode -ne 1 -or $reports[2].mode -ne 2){throw 'Incomplete captured comparison'}
  foreach($x in $reports){
   if($x.kind -ne 'packed_probability_capture' -or $x.query_count -ne $tokens -or $x.query_start -ne 16384 -or
    $x.key_tokens -ne 16384+$tokens -or $x.query_batch -ne 128 -or $x.slabs -ne ($tokens/128) -or
    $x.original_cpu_dot_checks -ne ($tokens*2) -or $x.storage_formats -ne 3 -or $x.original_gb10_context_cells -ne 4194304 -or
    $x.extended_queries -ne $tokens-1024 -or $x.candidate_checks -ne $reports[0].candidate_checks -or
    -not $x.complete_candidate_identity -or -not $x.owner_stage_order -or -not $x.every_attempt_checked -or
    $x.reference_is_compute_input -or $x.model_loaded -or $x.performance_acceptance){throw 'Captured in-place probability boundary failed'}
   if($x.completed_host_samples_ms.Count -ne 3){throw 'Missing complete timings'}
   foreach($ms in $x.completed_host_samples_ms){if([double]::IsNaN($ms) -or [double]::IsInfinity($ms) -or $ms -le 0){throw 'Invalid completed time'}}
  }
  if($reports[1].maximum_scratch_bytes -ne $reports[2].maximum_scratch_bytes){throw 'Candidate scratch owners differ'}
  for($i=0;$i -lt 3;$i++){if($reports[$i].storage_format -ne $m.storage_formats[$i] -or $reports[$i].probability_read_bytes -ne $m.probability_read_bytes[$i]){throw 'Storage mode metadata differs'}}
  if($reports[0].maximum_scratch_bytes-$reports[1].maximum_scratch_bytes -ne (128L*16*(16384+$tokens)*2)){throw 'In-place scratch size differs'}
 }
 foreach($x in $reports){foreach($key in @('payloads_and_unused_scores_bitexact','native_and_replayed_raw_surfaces_bitexact',
  'nonzero_output_offset','undersized_rejected','guards_and_inputs_pass')){if(-not $x.$key){throw ('Comparison failed: '+$key)}}}
 foreach($input in $spec.input_files){if((Get-FileHash $input.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $input.sha256){throw 'Input changed during run'}}
}
